def semver_sort(versions):
    def parse_key(v):
        # strip build metadata
        core = v.split('+', 1)[0]
        if '-' in core:
            main, prerelease = core.split('-', 1)
            has_pre = 0
        else:
            main = core
            prerelease = None
            has_pre = 1

        major, minor, patch = (int(x) for x in main.split('.'))

        if prerelease is not None:
            ids = prerelease.split('.')
            pre_key = []
            for ident in ids:
                if ident.isdigit():
                    pre_key.append((0, int(ident)))
                else:
                    pre_key.append((1, ident))
            pre_key = tuple(pre_key)
        else:
            pre_key = ()

        return (major, minor, patch, has_pre, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse_key(pair[1]), pair[0]))
    return [v for _, v in indexed]

